challenge_result.network_analysis:
{
  "summary": "The media plane is down due to a data plane fault localized at the UPF, which is dropping all outbound packets on the N3 interface while still receiving inbound traffic.",
  "layer_status": {
    "core": {
      "rating": "red",
      "evidence": [
        "derived.upf_activity_during_calls:drop:MEDIUM",
        "normalized.upf.gtp_outdatapktn3upf_per_ue:shift:MEDIUM"
      ],
      "note": "The UPF shows signs of complete downlink failure. Inbound N3 traffic is extremely high, while outbound is zero. This points to a critical fault within the UPF."
    },
    "ims": {
      "rating": "yellow",
      "evidence": [
        "derived.rtpengine_loss_ratio:spike:MEDIUM"
      ],
      "note": "RTPEngine is reporting high packet loss, which is a symptom of the upstream UPF failure. The IMS signaling plane itself shows some anomalies but they are likely downstream effects of the media plane collapse."
    },
    "ran": {
      "rating": "green",
      "evidence": [],
      "note": "No direct evidence of a RAN failure. The issue appears to be located within the core network."
    },
    "infrastructure": {
      "rating": "green",
      "evidence": [],
      "note": "All network functions are running and network links are active. The failure is not at the infrastructure level."
    }
  },
  "hypotheses": [
    {
      "id": "h1",
      "statement": "UPF is the source of the media plane failure; it is receiving traffic from the RAN but dropping all corresponding outbound packets toward the gNB on the N3 interface.",
      "primary_suspect_nf": "upf",
      "supporting_events": [
        "core.upf.activity_during_calls_collapsed"
      ],
      "explanatory_fit": 0.9,
      "falsification_probes": [
        "Check UPF's internal packet drop counters; if they are not incrementing, it would contradict the hypothesis that the UPF itself is dropping packets.",
        "A `measure_rtt` probe from UPF to the gNB (`nr_gnb`) returning 0% loss would suggest the UPF-to-gNB path is healthy, shifting the focus to UPF's internal logic."
      ],
      "specificity": "specific"
    },
    {
      "id": "h2",
      "statement": "RTPEngine is the source of the media plane packet loss, causing the degradation in call quality.",
      "primary_suspect_nf": "rtpengine",
      "supporting_events": [],
      "explanatory_fit": 0.4,
      "falsification_probes": [
        "The causal chain `rtpengine_media_degradation` contains a negative branch `n3_user_plane_unaffected` that states UPF N3 counters should be normal during a localized RTPEngine fault. The observed anomaly in UPF counters strongly contradicts a localized RTPEngine failure.",
        "A `measure_rtt` probe between RTPEngine and UPF showing no packet loss would indicate the path is clean, making an RTPEngine-based fault less likely."
      ],
      "specificity": "moderate"
    }
  ]
}

challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "UPF is the source of the media plane failure; it is receiving traffic from the RAN but dropping all corresponding outbound packets toward the gNB on the N3 interface.",
      "primary_suspect_nf": "upf",
      "probes": [
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check the downlink/outbound packet rate from the UPF. Use source: upf.gtp_outdatapktn3upf_per_ue",
          "expected_if_hypothesis_holds": "The probe reading for gtp_outdatapktn3upf_per_ue shows a deviation matching 'drop' or 'zero'.",
          "falsifying_observation": "The probe reading for gtp_outdatapktn3upf_per_ue is within its typical range.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check the uplink/inbound packet rate to the UPF. Use source: upf.gtp_indatapktn3upf_per_ue",
          "expected_if_hypothesis_holds": "The probe reading for gtp_indatapktn3upf_per_ue is within its typical range, indicating traffic is arriving at the UPF.",
          "falsifying_observation": "The probe reading for gtp_indatapktn3upf_per_ue shows a deviation matching 'zero'. This would suggest no traffic is reaching the UPF, making it unlikely to be the primary source of the drop.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check the packet loss ratio reported by the downstream RTPEngine. Use source: ims.rtpengine.loss_ratio",
          "expected_if_hypothesis_holds": "The probe reading for loss_ratio shows a 'spike', consistent with an upstream packet drop.",
          "falsifying_observation": "The probe reading for loss_ratio is within its typical range (0.0, 0.1), suggesting no significant end-to-end packet loss is being detected.",
          "conflates_with": []
        }
      ],
      "notes": "This plan uses KB-curated probes for h1 to verify the specific claim of one-way traffic drop at the UPF. It checks the outbound rate (the problem), the inbound rate (to rule out lack of traffic), and the downstream impact at RTPEngine."
    },
    {
      "hypothesis_id": "h2",
      "hypothesis_statement": "RTPEngine is the source of the media plane packet loss, causing the degradation in call quality.",
      "primary_suspect_nf": "rtpengine",
      "probes": [
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check for any internal errors reported by RTPEngine. Use source: rtpengine.errors_per_second",
          "expected_if_hypothesis_holds": "The probe reading for errors_per_second shows a 'spike', indicating active relay-loop errors.",
          "falsifying_observation": "The probe reading for errors_per_second is 'zero'.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check if the UPF data plane is collapsed, which would contradict a localized RTPEngine fault. Use source: upf.activity_during_calls",
          "expected_if_hypothesis_holds": "The probe reading for upf.activity_during_calls is within its typical range (0.3, 1.0), indicating that media flow through the UPF is still occurring.",
          "falsifying_observation": "The probe reading for upf.activity_during_calls shows a 'drop', indicating a collapse of the data plane at the UPF, which is inconsistent with a fault localized to RTPEngine.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Confirm the presence of the symptom (packet loss) at RTPEngine. Use source: rtpengine.loss_ratio",
          "expected_if_hypothesis_holds": "The probe reading for loss_ratio shows a 'spike'.",
          "falsifying_observation": "The probe reading for loss_ratio is within its typical range (0.0, 0.1), which would mean the primary symptom for this hypothesis is absent.",
          "conflates_with": []
        }
      ],
      "notes": "This plan tests the weaker hypothesis h2. The key falsification probe checks the state of the UPF. According to the NA report and KB hints, a localized RTPEngine fault should not cause the UPF's N3 counters to collapse completely."
    }
  ]
}
